return ['domain'=>NULL,'plural-forms'=>'nplurals=2; plural=(n > 1);','language'=>'fr','project-id-version'=>'Wbcom Designs - BuddyPress Group Reviews 3.9.0','pot-creation-date'=>'2026-07-17T10:19:11+00:00','po-revision-date'=>'2026-07-21T00:00:00+00:00','x-generator'=>'WP-CLI 2.12.0','messages'=>['Wbcom Designs - BuddyPress Group Reviews'=>'Wbcom Designs - BuddyPress Group Reviews','https://wbcomdesigns.com/contact/'=>'https://wbcomdesigns.com/contact/','This plugin allows BuddyPress Members to give reviews to BuddyPress groups on the site. The review form allows users to give text reviews and even rate the group based on multiple criteria.'=>'Ce plugin permet aux membres de BuddyPress de laisser des avis sur les groupes BuddyPress du site. Le formulaire d\'avis permet aux utilisateurs de laisser des avis textuels et même d\'évaluer le groupe selon plusieurs critères.','Wbcom Designs'=>'Wbcom Designs','http://wbcomdesigns.com'=>'http://wbcomdesigns.com','BuddyPress Group Reviews'=>'BuddyPress Group Evaluations','Are you enjoying BuddyPress Group Reviews?'=>'Tu aimes BuddyPress Group Reviews ?','We hope you\'re enjoying %1$s! Could you please do us a BIG favor and give it a 5-star rating on WordPress to help us spread the word and boost our motivation?'=>'Nous espérons que tu aimes %1$s ! Peux-tu nous faire un GRAND faveur et lui donner une note de 5 étoiles sur WordPress pour nous aider à faire connaître et nous motiver ?','Leave a Review'=>'Laisser un avis','No thanks / I already have'=>'Non merci / Je l\'ai déjà fait','Reviews'=>'Évaluations','Review'=>'Évaluation','Add New Review'=>'Ajouter une Évaluation','New Review'=>'Laisser une Évaluation','View Reviews'=>'Voir les Évaluations','All Reviews'=>'Toutes les Évaluations','Search Reviews'=>'Recherche les Évaluations','Parent Review'=>'Revue Parent','No Review Found'=>'Aucune Evaluation Trouvée','No Review Found In Trash'=>'Aucune Evaluation Trouvée dans la Poubelle','Search Categories'=>'Chercher les Catégories',